/**
 * generated by stackra gen from src/routes/<name>/ (every *.route.ts) — do not edit
 * Purpose: every route by its snake_case key (the route folder's name) as a `RouteRef`:
 *          layouts, frames, menus, pages and data navigate with `Routes.<key>`
 *          (`navigate.to(Routes.product, params)`, `ctx.redirect(Routes.landing)`,
 *          `m.route(Routes.store)`), never with the route class.
 * Boundary: data plus types. The route classes are imported as types only, so importing this file
 *           never loads a route module and no layout, menu or page can close an import cycle
 *           through it (links point down: app shell ← layout ← route → page). The router mounts
 *           the classes themselves from gen's route tree, which is the only importer of a route
 *           module.
 * Runtime: isomorphic
 */
import { routeRef } from "@stackra/navigation";
import type { ContactRoute } from "#src/routes/contact/contact.route";
import type { LandingRoute } from "#src/routes/landing/landing.route";
import type { PageRoute } from "#src/routes/page/page.route";
import type { PricingRoute } from "#src/routes/pricing/pricing.route";
import type { ProductRoute } from "#src/routes/product/product.route";
import type { StoreRoute } from "#src/routes/store/store.route";

/** Route key → typed route reference; the keys equal the route keys in stackra.manifest.json. */
export const Routes = {
  landing: routeRef<typeof LandingRoute>("landing"),
  pricing: routeRef<typeof PricingRoute>("pricing"),
  contact: routeRef<typeof ContactRoute>("contact"),
  store: routeRef<typeof StoreRoute>("store"),
  product: routeRef<typeof ProductRoute>("product"),
  page: routeRef<typeof PageRoute>("page"),
} as const;

/** One route key; a document's call to action holds one. */
export type RouteKey = keyof typeof Routes;
